DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_catalog.pg_auth_members am
     JOIN pg_catalog.pg_roles g ON g.oid = am.roleid
     WHERE g.rolname = ANY (ARRAY['jale_digest_enumerator', 'jale_rls_relationship_reader'])
       AND (am.inherit_option OR am.set_option)
  ) THEN
    RAISE EXCEPTION 'migration 106: a membership window on a helper owner is still open';
  END IF;
END;
$$;

